function renderArchive(){const root=$('#archive-list'),filter=$('#archive-filter')?.value||'all',categories=[...new Set([...archiveCategories,...state.documents.map(d=>d.category).filter(Boolean)])].sort((a,b)=>a.localeCompare(b,'pt-BR'));if($('#archive-filter')){const selected=$('#archive-filter').value;$('#archive-filter').innerHTML='<option value="all">Todas as categorias</option>'+categories.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}const list=state.documents.filter(d=>filter==='all'||d.category===filter).sort((a,b)=>companyName(a.companyId).localeCompare(companyName(b.companyId),'pt-BR')||a.category.localeCompare(b.category,'pt-BR')||(b.documentDate||b.createdAt||'').localeCompare(a.documentDate||a.createdAt||''));if($('#archive-count'))$('#archive-count').textContent=`${list.length} documento(s)`;if(root)root.innerHTML=list.length?list.map(d=>`<tr><td>${esc(companyName(d.companyId))}</td><td><span class="badge ok">${esc(d.category)}</span></td><td><strong>${esc(d.type||d.name)}</strong><br><small>${esc(d.name)}</small></td><td>${fmt(d.documentDate)}</td><td>${fmt(d.validity)}</td><td>${esc(d.source||'LiciDoc')}${d.sourceFolder?`<br><small>${esc(d.sourceFolder)}</small>`:''}</td><td><button class="link" data-document="${esc(d.filePath)}">Abrir</button>${deleteButton('document',d.id,'Excluir')}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">Nenhum documento arquivado nesta categoria.</td></tr>'}
